import sqlite3

def setup_db():
    conn = sqlite3.connect('magaza.db')
    cursor = conn.cursor()

    # Veritabanını temizle ve şemayı oluştur
    cursor.executescript('''
        DROP TABLE IF EXISTS iadeler;
        DROP TABLE IF EXISTS siparis_kalemleri;
        DROP TABLE IF EXISTS siparisler;
        DROP TABLE IF EXISTS urunler;
        DROP TABLE IF EXISTS musteriler;

        CREATE TABLE musteriler (id INTEGER PRIMARY KEY, ad TEXT NOT NULL, sehir TEXT NOT NULL, kayit_tarihi TEXT NOT NULL);
        CREATE TABLE urunler (id INTEGER PRIMARY KEY, ad TEXT NOT NULL, kategori TEXT NOT NULL, fiyat REAL NOT NULL);
        CREATE TABLE siparisler (id INTEGER PRIMARY KEY, musteri_id INTEGER NOT NULL REFERENCES musteriler(id), tarih TEXT NOT NULL);
        CREATE TABLE siparis_kalemleri (siparis_id INTEGER NOT NULL REFERENCES siparisler(id), urun_id INTEGER NOT NULL REFERENCES urunler(id), adet INTEGER NOT NULL, birim_fiyat REAL NOT NULL);
        CREATE TABLE iadeler (id INTEGER PRIMARY KEY, siparis_id INTEGER NOT NULL REFERENCES siparisler(id), urun_id INTEGER NOT NULL REFERENCES urunler(id), adet INTEGER NOT NULL);
    ''')

    # Örnek Veriler
    musteriler = [
        (1, 'Ahmet Yılmaz', 'İstanbul', '2023-01-01'),
        (2, 'Ayşe Demir', 'Ankara', '2023-02-15'),
        (3, 'Mehmet Kaya', 'İzmir', '2023-03-10'),
        (4, 'Canan Öz', 'Bursa', '2023-04-20')
    ]
    urunler = [(1, 'Laptop', 'Elektronik', 15000), (2, 'Mouse', 'Elektronik', 500), (3, 'Klavye', 'Elektronik', 1000)]

    siparisler = [
        (1, 1, '2023-01-10'), (2, 1, '2023-02-15'), (3, 1, '2023-03-20'), (4, 1, '2023-04-25'), (5, 1, '2023-05-30'), # Ahmet: 5 ay
        (6, 2, '2023-01-10'), (7, 2, '2023-03-10'), (8, 2, '2023-04-10'), # Ayşe: 1 ay, sonra 2 ay (tek değil) - asıl soruya göre ay bazında: 2023-01, 2023-03, 2023-04 -> 2023-03, 2023-04 (2 ay)
        (9, 3, '2023-01-05'), (10, 3, '2023-02-15'), (11, 3, '2023-03-20'), # Mehmet: 3 ay
        (12, 4, '2023-01-01'), (13, 4, '2023-02-01'), (14, 4, '2023-03-01'), (15, 4, '2023-01-15') # Canan: 2023-01, 02, 03 (3 ay)
    ]

    cursor.executemany('INSERT INTO musteriler VALUES (?,?,?,?)', musteriler)
    cursor.executemany('INSERT INTO urunler VALUES (?,?,?,?)', urunler)
    cursor.executemany('INSERT INTO siparisler VALUES (?,?,?)', siparisler)

    conn.commit()
    conn.close()

setup_db()

